INSERT INTO "system_settings" ("key","value","value_type","category","label","description","updated_at","updated_by") VALUES('post_visit_email_body',replace('Hello {{client_first_name}},\n\nIt was a pleasure meeting with you today at {{property_address}}!\n\nOur team is now putting together your estimate for the {{job_type}} project. You can expect to receive it within the next 1–2 business days for your review.\n\nIf you have any questions in the meantime, don''t hesitate to reach out.\n\nTony Columbus\nColumbus Home Solutions\n501-263-2050','\n',char(10)),'string','notifications','Post-Visit Follow-Up — Email Body','Body for the post-visit follow-up email.','2026-06-27 20:01:41','tony@homesolutionsar.com');
