INSERT INTO "saved_reviews" ("id","reviewer_name","review_date","rating","review_text","source","is_active","sort_order","created_at") VALUES('rev-001','Sarah M.','2025-11-15',5,'Tony and his team did an incredible job on our garage conversion. Professional from start to finish, always on time, and the quality of work exceeded our expectations. Highly recommend Columbus Home Solutions!','google',1,1,'2026-05-29 19:07:35');
INSERT INTO "saved_reviews" ("id","reviewer_name","review_date","rating","review_text","source","is_active","sort_order","created_at") VALUES('rev-002','James & Linda K.','2025-09-22',5,'We hired CHS for a full bathroom remodel and could not be happier. Tony kept us informed every step of the way with photos and updates. The finished product looks amazing. Fair pricing and honest work.','google',1,2,'2026-05-29 19:07:35');
INSERT INTO "saved_reviews" ("id","reviewer_name","review_date","rating","review_text","source","is_active","sort_order","created_at") VALUES('rev-003','Marcus D.','2026-01-08',5,'Columbus Home Solutions built a beautiful deck for us. The crew was respectful of our property, cleaned up every day, and finished ahead of schedule. Tony is the kind of contractor you can trust. Five stars.','google',1,3,'2026-05-29 19:07:35');
