INSERT INTO "notification_templates" ("id","trigger_event","name","recipient_type","channel","subject","body_template","merge_fields","is_active","delay_minutes","send_time","phase","sort_order","created_at","updated_at") VALUES('nt-estimate-sent-email','estimate_sent','Estimate Ready Email','client','email','Your Estimate is Ready — {{job_title}}',replace('Your estimate for {{job_title}} is ready. View and approve here: {{estimate_link}}\n\nBefore you decide, take a look at what makes us different — attached is our <a href="https://client.homesolutionsar.com/api/public/company-assets/one-sheet">One Sheet</a> (see how we compare to typical contractors) and our <a href="https://client.homesolutionsar.com/api/public/company-assets/price-match-guarantee">Price Match Guarantee</a>, backed by a 5-year workmanship warranty most companies won''t match.\n\nFinancing is available through our partner Wisetack. Check your options in seconds with no impact to your credit score: https://wisetack.us/#/g1wjjq5/prequalify','\n',char(10)),'["job_title","estimate_link"]',1,0,NULL,'estimating',7,'2026-05-29 19:07:35','2026-08-11 17:33:03');
