INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('48ae0340-61d0-49f7-8d1f-47d5935f2ca9','seasonal_tips','published','Arkansas summers hit different! 🌡️ Simple upgrades can make a huge difference in keeping your home cool and your energy bills manageable. Consider adding ceiling fans in key areas, upgrading to energy-efficient windows, or improving your attic insulation. Even small changes like weatherstripping around doors and windows can help your AC work less overtime. What''s your go-to trick for staying cool at home?','["#BeatTheHeat","#SummerUpgrades","#LittleRock","#HomeRemodel","#CentralArkansas","#HVAC","#ContractorLife","#CoolingSystem","#HomeImprovement","#ArkansasHomes","#BeforeAndAfter","#EnergyEfficient","#SummerReady"]','both','2026-06-03T08:00:00','2026-06-03 08:00:25',NULL,NULL,NULL,'SIMFB-48ae0340-1780473625137','SIMIG-48ae0340-1780473625137','https://www.facebook.com/SIMFB-48ae0340-1780473625137','https://www.instagram.com/p/SIMIG-48ae0340-1780473625137',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-03 01:57:49','2026-06-03 01:54:33',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('729d6ed4-f10c-4064-8283-b395061f3483','tips_tricks','published','Planning a home project? Here are some key questions to ask before hiring any contractor: Are you licensed and insured? Can you provide local references? What''s included in your written estimate? How do you handle unexpected issues or changes? A reputable contractor will welcome these questions and provide clear, honest answers. Your home deserves quality work from professionals you can trust.','["#LittleRock","#CentralArkansas","#ContractorQuestions","#HomeRemodel","#ContractorTips","#NorthLittleRock","#HiringContractors","#HomeImprovement","#ContractorLife","#RenovationTips","#BeforeAndAfter","#Arkansas","#HomeRenovation"]','both','2026-06-04T18:00:00','2026-06-03 20:20:11',NULL,NULL,'/api/social-posts/729d6ed4-f10c-4064-8283-b395061f3483/image','SIMFB-729d6ed4-1780518011680','SIMIG-729d6ed4-1780518011680','https://www.facebook.com/SIMFB-729d6ed4-1780518011680','https://www.instagram.com/p/SIMIG-729d6ed4-1780518011680',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-03 20:00:29','2026-06-03 01:54:46',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('adc92b74-8c95-419d-bf1f-2aae6625db49','tips_tricks','published','When selecting finishes for your Arkansas home, think long-term! Quartz countertops resist our humidity and daily wear beautifully. Luxury vinyl plank flooring handles everything from muddy boots to pet accidents while looking like real hardwood. And quality fixtures? They''re investments that pay off in both daily function and resale value. We always tell our Little Rock area clients: spend a little more upfront on finishes that will serve your family for decades.','["#DurableFinishes","#LittleRock","#HomeRemodel","#QualityFirst","#CentralArkansas","#ContractorLife","#LongLastingResults","#NorthLittleRock","#BeforeAndAfter","#HomeImprovement","#BuiltToLast","#GarageConversion","#ArkansasHomes","#ProfessionalWork","#HomeRenovation"]','both','2026-06-06 15:31:03','2026-06-06 15:45:19',NULL,NULL,'/api/social-posts/adc92b74-8c95-419d-bf1f-2aae6625db49/image',NULL,'18595115920036000',NULL,'https://www.instagram.com/p/18595115920036000',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-05 04:17:07','2026-06-03 01:54:57',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('c1e7e01f-9d4e-458f-b449-d5617cd1fb5c','seasonal_tips','published','Arkansas summers are no joke! 🌡️ A few smart upgrades can make a huge difference in keeping your home cool and comfortable. Consider adding ceiling fans in bedrooms and living areas, upgrading to energy-efficient windows, or improving your attic insulation. Even simple fixes like sealing air leaks around doors and windows can cut your cooling costs significantly. Your family (and your electric bill) will thank you!','["#BeatTheHeat","#LittleRock","#HomeRemodel","#SummerUpgrades","#CentralArkansas","#ContractorLife","#CoolingUpgrades","#NorthLittleRock","#BeforeAndAfter","#EnergyEfficient","#ArkansasContractor","#HomeImprovement","#SummerReady"]','both','2026-06-06 15:31:03','2026-06-06 15:45:22',NULL,NULL,'/api/social-posts/c1e7e01f-9d4e-458f-b449-d5617cd1fb5c/image',NULL,'18087078362083793',NULL,'https://www.instagram.com/p/18087078362083793',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-05 04:17:40','2026-06-03 01:55:08',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('77d6f61d-5104-4c6b-bc87-56e0c2839a1a','seasonal_tips','failed','Summer in Arkansas means it''s time to make the most of your outdoor space! 🌞 Planning a deck or patio project? Here''s a pro tip: choose materials that can handle our humid summers and occasional storms. Composite decking and stamped concrete are popular choices here in central Arkansas because they''re low-maintenance and built to last. The key is proper drainage and ventilation – trust us, your future self will thank you when you''re enjoying cool evenings on a deck that still looks great years later.','["#OutdoorLiving","#DeckLife","#PatioDesign","#LittleRock","#CentralArkansas","#HomeRemodel","#SummerVibes","#BackyardGoals","#ContractorLife","#BeforeAndAfter","#OutdoorEntertaining","#ArkansasContractor","#DeckBuilder"]','both','2026-06-06 14:53:48',NULL,NULL,NULL,'/api/social-posts/77d6f61d-5104-4c6b-bc87-56e0c2839a1a/image',NULL,NULL,NULL,NULL,NULL,'instagram:Media ID is not available; facebook:Media ID is not available','ai_schedule','tony@homesolutionsar.com','2026-06-05 12:14:16','2026-06-03 01:55:20',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('882f3a11-5666-488c-b5a8-28fe95a4a880','tips_tricks','published',replace('Planning a remodel? Here''s how to budget smart and avoid those heart-stopping surprises! 💡 Start with your must-haves vs. nice-to-haves, then add 15-20% for unexpected discoveries (trust us, old homes love to surprise us). Get detailed quotes from licensed contractors and ask about potential issues upfront. A little extra planning now saves major headaches later!\n\nYour Arkansas home deserves quality work done right the first time. Questions about your next project? We''re here to help! 🏠','\n',char(10)),'["#BudgetingTips","#LittleRock","#HomeRemodel","#RenovationPlanning","#CentralArkansas","#ContractorLife","#NoSurprises","#RemodelBudget","#NorthLittleRock","#HomeImprovement","#ConstructionCosts","#RenovationTips","#ArkansasContractors"]','both','2026-06-06 15:31:03','2026-06-06 15:45:24',NULL,NULL,'/api/social-posts/882f3a11-5666-488c-b5a8-28fe95a4a880/image',NULL,'18103595855084616',NULL,'https://www.instagram.com/p/18103595855084616',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-05 12:14:48','2026-06-03 01:55:33',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('993ee108-9805-4a9f-8d5d-92ba95492b58','seasonal_tips','failed','Beat the Arkansas heat and lower those summer electric bills! 💡 Simple upgrades like adding insulation to your attic, sealing air leaks around windows and doors, or installing a programmable thermostat can make a huge difference. Even upgrading to energy-efficient windows helps keep that cool air where it belongs – inside your home. Small investments now mean big savings all summer long.','["#LittleRock","#SummerEnergySavings","#HomeRemodel","#CentralArkansas","#ContractorLife","#EnergyEfficientHomes","#BeforeAndAfter","#HVAC","#InsulationUpgrade","#NorthLittleRock","#GreenBuilding","#WindowReplacement","#ArkansasContractor","#CoolingSolutions","#HomeImprovement"]','both','2026-06-06 14:53:48',NULL,NULL,NULL,'/api/social-posts/993ee108-9805-4a9f-8d5d-92ba95492b58/image',NULL,NULL,NULL,NULL,NULL,'instagram:Media ID is not available; facebook:Media ID is not available','ai_schedule','tony@homesolutionsar.com','2026-06-05 12:23:51','2026-06-03 01:55:44',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('1b1aafed-11d6-4a66-ac01-177553c51eed','manual','published','Winter''s coming, Arkansas homeowners! 🏠 Here''s a quick tip: check your gutters now before the next storm hits. Clogged gutters can lead to water damage, foundation issues, and ice dams. A simple afternoon of cleaning could save you thousands in repairs. If you''re not comfortable getting on that ladder, we''re always here to help our neighbors in Little Rock, Conway, and North Little Rock stay ahead of costly problems.',NULL,'both',NULL,'2026-06-03 02:01:33',NULL,NULL,NULL,'SIMFB-1b1aafed-1780452093637','SIMIG-1b1aafed-1780452093637','https://www.facebook.com/SIMFB-1b1aafed-1780452093637','https://www.instagram.com/p/SIMIG-1b1aafed-1780452093637',NULL,NULL,'manual','tony@homesolutionsar.com','2026-06-03 02:01:31','2026-06-03 02:00:54',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('6c284db6-6e82-4df5-9ad5-b196754ca5ce','seasonal_tips','failed','Summer heat got you cranking up the AC? Here are a few upgrades that can keep your home cooler naturally: Install ceiling fans to improve air circulation, add window treatments like cellular shades to block UV rays, and consider upgrading to energy-efficient windows. Small changes can make a big difference in your comfort and energy bills! What''s your go-to trick for staying cool at home?','["#BeatTheHeat","#LittleRock","#HomeRemodel","#SummerUpgrades","#CentralArkansas","#HVAC","#ContractorLife","#CoolingSystem","#HomeImprovement","#ArkansasContractor","#EnergyEfficient","#BeforeAndAfter","#IndoorComfort"]','both','2026-06-06 14:53:48',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'instagram:instagram_not_connected; facebook:instagram_not_connected','ai_schedule','tony@homesolutionsar.com','2026-06-05 12:26:24','2026-06-05 12:25:24',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('62a3bfe9-f3d3-4fba-b6e5-ce0547d2b3eb','tips_tricks','failed','Thinking about a home improvement project? Here are some key questions to ask any contractor before signing on the dotted line: Are you licensed and insured? Can you provide local references? What''s included in your warranty? How do you handle unexpected issues or changes? A trustworthy contractor will welcome these questions and provide clear, honest answers. Your home is your biggest investment – make sure you''re working with someone who respects that.','["#LittleRock","#CentralArkansas","#ContractorQuestions","#HomeRemodel","#ContractorTips","#HomeImprovement","#ARHomeBuyers","#RenovationAdvice","#ContractorVetting","#HomeReno","#LittleRockHomes","#ContractorLife","#BuildSmart"]','both','2026-06-06 14:53:48',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'instagram:instagram_not_connected; facebook:instagram_not_connected','ai_schedule','tony@homesolutionsar.com','2026-06-05 12:26:38','2026-06-05 12:25:35',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('10d0833b-16da-4c40-9c72-da238b070c88','tips_tricks','published','Choosing the right finishes for your Arkansas home can save you time and money in the long run! When selecting materials, consider our humid climate and temperature swings. Opt for moisture-resistant options in bathrooms, durable flooring that can handle muddy boots, and exterior finishes that stand up to our unpredictable weather. A little extra investment upfront means fewer repairs down the road. What questions do you have about materials for your next project?','["#ColumbusHomeSolutions","#HomeSolutionsAR","#CentralArkansasContractor","#LittleRock","#CentralArkansas","#Arkansas","#HomeImprovement","#HomeRenovation","#HomeRemodel","#Craftsmanship","#QualityWork","#BuildingDreams","#CustomerSatisfaction","#LicensedContractor","#FreeEstimate"]','both','2026-06-06 15:31:03','2026-06-06 15:45:27',NULL,NULL,'/api/social-posts/10d0833b-16da-4c40-9c72-da238b070c88/image',NULL,'17885421993570843',NULL,'https://www.instagram.com/p/17885421993570843',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-05 22:34:36','2026-06-05 12:25:45',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('02133575-4a6a-4480-ba4a-1dd82d361176','seasonal_tips','failed','Arkansas summers can be brutal! Here are some upgrades that''ll keep you cool and your energy bills in check: Install ceiling fans in every room (they can make spaces feel 6-8 degrees cooler), upgrade to energy-efficient windows with Low-E coatings, and don''t forget proper attic insulation – it''s your home''s first defense against that blazing summer sun. Small improvements can make a huge difference in comfort and cost.','["#BeatTheHeat","#SummerUpgrades","#LittleRock","#HomeRemodel","#HVAC","#CentralArkansas","#ContractorLife","#CoolingSystem","#BeforeAndAfter","#ArkansasHomes","#EnergyEfficient","#SummerReady","#NorthLittleRock"]','both','2026-06-06 14:53:48',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'instagram:instagram_not_connected; facebook:instagram_not_connected','ai_schedule','tony@homesolutionsar.com','2026-06-05 22:34:50','2026-06-05 12:25:56',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('ab97937a-a031-49c9-aa63-aed08e0005af','seasonal_tips','published','Summer in Arkansas means it''s time to make the most of your outdoor space! Whether you''re dreaming of a new deck for morning coffee or a patio perfect for evening gatherings, now''s the ideal time to plan your project. Consider materials that can handle our humid summers and occasional storms – composite decking and stamped concrete are popular choices here in central Arkansas. Pro tip: proper drainage and shade planning will make your outdoor space comfortable even on those 90-degree July days.','["#OutdoorLiving","#DeckLife","#PatioDesign","#LittleRock","#CentralArkansas","#HomeRemodel","#SummerVibes","#BackyardGoals","#ContractorLife","#BeforeAndAfter","#OutdoorSpaces","#ArkansasContractor","#DeckBuilder","#PatioProject","#HomeImprovement"]','both','2026-06-17T08:00:00','2026-06-29 22:15:36',NULL,NULL,'/api/social-posts/ab97937a-a031-49c9-aa63-aed08e0005af/image',NULL,'17918986251182999',NULL,'https://www.instagram.com/p/17918986251182999',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-29 22:03:03','2026-06-05 12:26:08',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('72724803-b931-45a6-86b9-771d6b6ecd28','tips_tricks','failed','Planning a remodel in central Arkansas? Here''s the truth: surprises happen, but you can plan for them! Start with a detailed scope of work, get multiple quotes, and always add 15-20% to your budget for unexpected discoveries (like that plumbing behind the wall that needs updating). We''ve helped hundreds of Little Rock area families navigate their remodeling journeys, and the most successful projects start with realistic expectations and honest conversations about costs.','["#BudgetingTips","#HomeRemodel","#LittleRock","#RenovationPlanning","#CentralArkansas","#ContractorLife","#HomeImprovement","#NorthLittleRock","#RemodelBudget","#NoSurprises","#Arkansas","#RenovationTips","#BeforeAndAfter"]','both','2026-06-24T23:00:00.000Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'instagram:instagram_not_connected; facebook:instagram_not_connected','ai_schedule','tony@homesolutionsar.com','2026-06-29 22:04:03','2026-06-05 12:26:19',0);
INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('c04ce73c-6b2e-4d34-92e2-82e66bf66368','seasonal_tips','published','Beat the Arkansas heat and lower your energy bills this summer! 💡 Simple upgrades like adding insulation to your attic, sealing air leaks around windows and doors, and installing ceiling fans can make a huge difference. Even switching to LED bulbs reduces heat buildup in your home. Small improvements, big savings! What energy-saving project is on your list this summer?','["#LittleRock","#CentralArkansas","#HomeRemodel","#EnergyEfficient","#SummerSavings","#ContractorLife","#BeforeAndAfter","#HomeImprovement","#ArkansasHomes","#CoolYourHome","#HVAC","#Insulation","#WindowReplacement"]','both','2026-06-30T13:00:00.000Z','2026-06-29 22:05:35',NULL,NULL,'/api/social-posts/c04ce73c-6b2e-4d34-92e2-82e66bf66368/image',NULL,'18204675454314483',NULL,'https://www.instagram.com/p/18204675454314483',NULL,NULL,'ai_schedule','tony@homesolutionsar.com','2026-06-29 22:04:39','2026-06-05 12:26:33',0);
