INSERT INTO "social_posts" ("id","post_type","status","caption","hashtags","platform","scheduled_date","published_date","job_id","photo_ids","ai_generated_image_url","facebook_post_id","instagram_post_id","facebook_url","instagram_url","engagement_data","rejection_reason","generated_by","approved_by","approved_date","created_at","image_variation_index") VALUES('73daaff4-2044-4e9c-8e9d-2cb797831af9','manual','published','Planning a home improvement project this year? Here''s a tip from our team: always tackle structural and electrical work first, then plumbing, followed by insulation and drywall. Flooring and paint come last! This sequence saves you from having to redo finished work when the next phase begins. We''ve learned this the hard way over our years serving Little Rock and Conway homeowners – proper sequencing makes all the difference in your timeline and budget.','[]','both','2026-06-06 17:17:40','2026-06-06 17:30:36',NULL,NULL,'/api/social-posts/73daaff4-2044-4e9c-8e9d-2cb797831af9/image',NULL,'18099465704163530',NULL,'https://www.instagram.com/p/18099465704163530',NULL,NULL,'manual','tony@homesolutionsar.com','2026-06-06 17:05:10','2026-06-06 17:04:23',0);
