INSERT INTO "google_reviews" ("id","google_review_id","reviewer_name","reviewer_photo_url","star_rating","comment_text","review_created_at","review_updated_at","reply_text","reply_sent_at","reply_source","matched_client_id","match_confidence","entry_source","synced_at","created_at") VALUES('216c14dc-6bb2-4d5a-b8a5-9b2076a5c55e','AbFvOqn1ibDsMdJiqdqFjxFY7AR129i_ebf_212Tt1S9zWztX90zPDkPPGG3ajF3zmji3qTmwkW7JQ','Harland Matthews','https://lh3.googleusercontent.com/a/ACg8ocIiaisWORBtnYQy5F9_8L1XdPcSZrN-etmR_94FR55KtP732A=s120-c-rp-mo-br100',5,'Columbus Home Solutions added an exterior door to the side of my garage. I discussed with Tony what I wanted to do and he came out and looked ar it. Within a couple of days he got back to me with an estimate that was very satisfactory. He was able to start on the project the next Monday. It only two days for his team to cut out the brick and inside sheet rock, install the 36 inch door and trim, paint the door, build the steps, and do the cleanup. Every one of his employees that I met was very friendly and professional and did an outstanding job. I could not be more pleased. I would definitely recommend Columbus Home Solutions.','2026-03-05T22:10:06.480432Z','2026-03-06T21:59:27.939622Z','Thank you for your generous feedback. We truly value your support and look forward to the opportunity to serve you again in the near future. Our team is pleased to hear about your positive experience.','2026-03-06T00:14:01.815614Z','external','Z2lkOi8vSm9iYmVyL0NsaWVudC8xMzEzODU3ODQ=','suggested','sync','2026-08-23 21:30:28','2026-07-20 02:06:44');
INSERT INTO "google_reviews" ("id","google_review_id","reviewer_name","reviewer_photo_url","star_rating","comment_text","review_created_at","review_updated_at","reply_text","reply_sent_at","reply_source","matched_client_id","match_confidence","entry_source","synced_at","created_at") VALUES('3ecf89f5-8be2-4093-a97f-d04236f7026a','AbFvOqlseKtl5pk4m0H39UPmz2S1WuUwvKJ0_lUIj58pYNmLGxEelCNC8oToEkEVO2FS5VV3PhI6_A','Lorie Johnson','https://lh3.googleusercontent.com/a-/ALV-UjXvqwi61N5LPb-8AXK1g6-UsAxKJ_7LWYpyM3IBYaxKXmLKmu_Z=s120-c-rp-mo-br100',5,'The painting crew took time to prepare the area for their work and the result was excellent. Because the weather was on the cool side, the paint took time to dry but it was worth the wait. The photos show the garage door, back door and the garage exit. Detail is an illustration of the expert application of the paint. No drips or spraying artifacts. I’m very happy with the work and recommend this company.','2026-02-10T16:03:18.792508Z','2026-02-10T16:03:18.792508Z','Thank you so much for your fantastic review! Our team is absolutely delighted that you loved the detailed, expert paint job, and we truly appreciate your wonderful recommendation!','2026-03-06T00:14:26.938441Z','external','Z2lkOi8vSm9iYmVyL0NsaWVudC8xMjc1NDE2MzE=','suggested','sync','2026-08-23 21:30:28','2026-07-20 02:06:44');
