PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE jobs (
  id TEXT PRIMARY KEY,                    
  job_number INTEGER,
  title TEXT,
  status TEXT,                            
  client_id TEXT REFERENCES clients(id),
  source TEXT,
  total REAL,
  created_at TEXT,                        
  start_at TEXT,
  completed_at TEXT,
  synced_at TEXT NOT NULL
, billing_model TEXT, property_address TEXT, property_city TEXT, property_state TEXT DEFAULT 'Arkansas', property_zip TEXT, job_type TEXT, lead_source TEXT, estimate_id TEXT, start_date TEXT, target_end_date TEXT, actual_end_date TEXT, contract_total REAL, deposit_amount REAL, deposit_paid INTEGER DEFAULT 0, portal_token TEXT, portal_type TEXT, notes TEXT, warranty_expiration TEXT, updated_at TEXT, created_by TEXT, conversion_complete INTEGER DEFAULT 0, conversion_reversed INTEGER DEFAULT 0, reversal_reason TEXT, reversed_at TEXT, lat REAL, lon REAL, data_source TEXT, payer_id TEXT REFERENCES payers(id), ai_closeout_review TEXT, ai_closeout_generated_at TEXT, assigned_to TEXT REFERENCES users(id), completion_package_sent_at TEXT, review_enabled INTEGER NOT NULL DEFAULT 1, review_received INTEGER NOT NULL DEFAULT 0, review_received_at TEXT, property_id TEXT REFERENCES properties(id), job_type_detail TEXT);
CREATE TABLE clients (
  id TEXT PRIMARY KEY,
  name TEXT,
  phone TEXT,
  email TEXT,
  address_street TEXT,
  address_city TEXT,
  address_state TEXT,
  address_postal TEXT,
  custom_fields TEXT,                     
  synced_at TEXT NOT NULL
, first_name TEXT, last_name TEXT, phone_secondary TEXT, mailing_address TEXT, mailing_city TEXT, mailing_state TEXT, mailing_zip TEXT, lead_source TEXT, high_level_contact_id TEXT, is_repeat_client INTEGER DEFAULT 0, review_requested INTEGER DEFAULT 0, google_review_left INTEGER DEFAULT 0, notes TEXT, last_interaction_date TEXT, created_at TEXT, updated_at TEXT, created_by TEXT, notification_preferences TEXT, qbo_customer_id TEXT, company_name TEXT, data_source TEXT, sms_opt_out INTEGER NOT NULL DEFAULT 0, sms_opt_out_at TEXT, referral_source_id TEXT REFERENCES referral_sources(id), is_test INTEGER NOT NULL DEFAULT 0);
CREATE TABLE quotes (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  quote_number INTEGER,
  status TEXT,                            
  subtotal REAL,
  created_at TEXT,
  transitioned_at TEXT,
  synced_at TEXT NOT NULL
, client_id TEXT REFERENCES clients(id));
CREATE TABLE invoices (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  status TEXT,
  total REAL,
  payments_total REAL,
  issued_date TEXT,
  due_date TEXT,
  synced_at TEXT NOT NULL
, invoice_number INTEGER, client_id TEXT, billing_model TEXT, invoice_type TEXT, title TEXT, description TEXT, amount REAL, tax_amount REAL DEFAULT 0, late_fee_amount REAL DEFAULT 0, credits_applied REAL DEFAULT 0, total_due REAL, sent_date TEXT, paid_date TEXT, paid_amount REAL, payment_method TEXT, stripe_payment_id TEXT, portal_link TEXT, cost_plus_cycle_id TEXT, milestone_number INTEGER, trade_line_item_id TEXT, notes TEXT, created_at TEXT, created_by TEXT, payment_token TEXT, viewed_date TEXT, qbo_invoice_id TEXT, qbo_synced_at  TEXT, data_source TEXT, line_item_ids TEXT, payer_id TEXT REFERENCES payers(id));
CREATE TABLE payments (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  invoice_id TEXT REFERENCES invoices(id),
  amount REAL,
  collected_at TEXT,                      
  synced_at TEXT NOT NULL
, client_id TEXT, payment_method TEXT, stripe_payment_id TEXT, stripe_fee REAL, convenience_fee REAL, net_amount REAL, received_date TEXT, deposited_date TEXT, notes TEXT, created_at TEXT, estimate_id TEXT, qbo_payment_id TEXT, qbo_synced_at  TEXT, data_source TEXT);
CREATE TABLE line_items (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  name TEXT,
  quantity REAL,
  unit_price REAL,
  unit_cost REAL,
  synced_at TEXT NOT NULL
);
CREATE TABLE expenses (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  amount REAL,
  description TEXT,
  incurred_at TEXT,
  synced_at TEXT NOT NULL
, vendor TEXT, receipt_r2_key TEXT, entered_via TEXT NOT NULL DEFAULT 'jobber', pushed_to_jobber_at TEXT, jobber_id TEXT, drive_mirrored_at TEXT, expense_type TEXT, incurred_date TEXT, estimate_line_item_id TEXT, receipt_photo_id TEXT, tax_category TEXT, is_1099_reportable INTEGER DEFAULT 0, sub_id TEXT, pushed_to_qbo INTEGER DEFAULT 0, qbo_transaction_id TEXT, created_at TEXT, created_by TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE leads (
  id TEXT PRIMARY KEY,
  name TEXT,
  phone TEXT,
  email TEXT,
  source TEXT,
  status TEXT,                            
  assigned_to TEXT,
  created_at TEXT,
  last_contact_at TEXT,
  synced_at TEXT NOT NULL
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  role TEXT NOT NULL,                     
  default_crew TEXT,
  current_job_id TEXT REFERENCES jobs(id),
  created_at TEXT NOT NULL,
  last_login_at TEXT,
  disabled INTEGER DEFAULT 0
, first_name TEXT, last_name TEXT, phone TEXT, is_active INTEGER DEFAULT 1, last_login TEXT, notification_preferences TEXT, updated_at TEXT, calendar_color TEXT DEFAULT '#3B82F6', business_phone TEXT);
CREATE TABLE estimates (
  id TEXT PRIMARY KEY,
  lead_id TEXT REFERENCES leads(id),
  status TEXT NOT NULL,                   
  jobber_quote_id TEXT,

  extracted_scope TEXT,                   
  extracted_items TEXT,                   

  line_items TEXT,                        
  subtotal REAL,
  total REAL,
  margin_percent REAL,

  created_at TEXT NOT NULL,
  created_by TEXT REFERENCES users(id),
  updated_at TEXT NOT NULL,
  sent_at TEXT
, estimate_number INTEGER, request_id TEXT, client_id TEXT, title TEXT, estimate_mode TEXT, billing_model TEXT, tax_amount REAL DEFAULT 0, deposit_amount REAL, deposit_type TEXT, deposit_percentage REAL, valid_days INTEGER DEFAULT 7, expiration_date TEXT, portal_token TEXT, include_reviews INTEGER DEFAULT 1, review_ids TEXT, include_contract INTEGER DEFAULT 1, contract_template_id TEXT, client_signature TEXT, signed_date TEXT, notes TEXT, version INTEGER DEFAULT 1, revised_from_id TEXT, viewed_date TEXT, approved_date TEXT, contract_text TEXT, data_source TEXT, is_current_version INTEGER NOT NULL DEFAULT 1, last_resent_at TEXT, deposit_payment_method TEXT, deposit_method_selected_at TEXT);
CREATE TABLE files (
  id TEXT PRIMARY KEY,                    
  r2_key TEXT NOT NULL UNIQUE,            
  filename TEXT NOT NULL,                 
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 TEXT,                            
  uploaded_by TEXT REFERENCES users(id),
  uploaded_at TEXT NOT NULL,

  
  job_id TEXT REFERENCES jobs(id),
  lead_id TEXT REFERENCES leads(id),
  estimate_id TEXT REFERENCES estimates(id),

  
  category TEXT,                          
                                          
                                          
  taken_at TEXT,                          

  
  captured_lat REAL,
  captured_lon REAL,
  captured_by_device TEXT,

  
  deleted_at TEXT,                        
  archived INTEGER DEFAULT 0              
);
CREATE TABLE file_tags (
  file_id TEXT REFERENCES files(id) ON DELETE CASCADE,
  tag TEXT NOT NULL,
  PRIMARY KEY (file_id, tag)
);
CREATE TABLE file_shares (
  id TEXT PRIMARY KEY,                    
  file_id TEXT REFERENCES files(id) ON DELETE CASCADE,
  shared_with_email TEXT,                 
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  last_viewed_at TEXT,
  view_count INTEGER DEFAULT 0
);
CREATE TABLE ai_generations (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,                     
  file_id TEXT REFERENCES files(id),
  prompt TEXT NOT NULL,
  model TEXT NOT NULL,                    
  cost_cents INTEGER,
  input_tokens INTEGER,
  output_tokens INTEGER,
  generated_at TEXT NOT NULL,
  generated_by TEXT REFERENCES users(id)
);
CREATE TABLE integrations (
  id TEXT PRIMARY KEY,                    
  kind TEXT NOT NULL,                     
  config TEXT,                            
  access_token TEXT,                      
  refresh_token TEXT,                     
  token_expires_at TEXT,
  last_synced_at TEXT,
  last_error TEXT,
  enabled INTEGER DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE sync_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_name TEXT NOT NULL,                 
  started_at TEXT NOT NULL,
  finished_at TEXT,
  status TEXT NOT NULL,                   
  rows_affected INTEGER DEFAULT 0,
  error_message TEXT,
  duration_ms INTEGER
, details TEXT);
CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT REFERENCES users(id),
  action TEXT NOT NULL,                   
  entity_type TEXT,
  entity_id TEXT,
  metadata TEXT,                          
  ip_address TEXT,
  user_agent TEXT,
  occurred_at TEXT NOT NULL
);
CREATE TABLE kv_cache (
  key TEXT PRIMARY KEY,                   
  value TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE notes (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  category TEXT,
  raw_text TEXT NOT NULL,
  summary TEXT,
  tags TEXT,
  tasks_extracted TEXT,
  task_count INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active',
  archived_at TEXT,
  meeting_source TEXT
, job_id TEXT);
CREATE TABLE subcontractors (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,

  company           TEXT,   -- Company / Individual (required in practice)
  trade             TEXT,   -- Trade / Scope (Electrical, Plumbing, etc.)
  primary_contact   TEXT,
  reference_type    TEXT,   -- General Contractor, Homeowner, Architect, …
  phone             TEXT,
  email             TEXT,
  city_state        TEXT,   -- "Dallas, TX"
  service_area      TEXT,
  license_number    TEXT,   -- "EC-123456 / TX"
  insurance_verified INTEGER NOT NULL DEFAULT 0,  -- 0/1
  years_worked      REAL,
  last_project      TEXT,
  last_project_date TEXT,   -- ISO YYYY-MM-DD
  rating            INTEGER,-- 1–5
  would_rehire      INTEGER,-- NULL unknown, 0 No, 1 Yes
  notes             TEXT,
  website           TEXT,
  follow_up_date    TEXT,   -- ISO YYYY-MM-DD
  active_status     TEXT NOT NULL DEFAULT 'Active'  -- Active | Inactive
, company_name TEXT, contact_name TEXT, insurance_on_file INTEGER DEFAULT 0, w9_on_file INTEGER DEFAULT 0, hourly_rate REAL, flat_rate_notes TEXT, is_active INTEGER DEFAULT 1, qbo_vendor_id   TEXT, tax_id TEXT, calendar_color TEXT DEFAULT '#10B981', coi_expiration_date TEXT, license_expiration_date TEXT, worker_type TEXT NOT NULL DEFAULT 'subcontractor', day_rate REAL);
CREATE TABLE sync_dead_letters (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_name TEXT NOT NULL,                 
  entity_type TEXT NOT NULL,              
  entity_id TEXT,                         
  payload TEXT,                           
  error_message TEXT NOT NULL,
  first_seen_at TEXT NOT NULL,            
  last_seen_at TEXT NOT NULL,             
  attempts INTEGER NOT NULL DEFAULT 1,
  resolved_at TEXT,                       
  last_attempt_status TEXT,               
  alerted_at TEXT                         
);
CREATE TABLE photos (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,                  
  taken_at TEXT,                             
  job_id TEXT,                               
  category TEXT NOT NULL DEFAULT 'progress', 
  r2_key TEXT NOT NULL,
  thumb_key TEXT NOT NULL,
  uploaded_by TEXT,                          
  gps_lat REAL,
  gps_lng REAL,
  tags TEXT,                                 
  caption TEXT,                              
  before_after_pair_id TEXT                  
, drive_mirrored_at TEXT, estimate_request_id TEXT, r2_thumbnail_key TEXT, r2_url TEXT, google_drive_id TEXT, photo_type TEXT, latitude REAL, longitude REAL, location_accuracy REAL, uploaded_at TEXT, synced_from_offline INTEGER DEFAULT 0, task_id TEXT, daily_log_id TEXT, is_annotated INTEGER DEFAULT 0, annotation_data TEXT, is_social_ready INTEGER DEFAULT 0, is_before_photo INTEGER DEFAULT 0, is_after_photo INTEGER DEFAULT 0, ai_tags TEXT, entered_via TEXT, is_active INTEGER DEFAULT 1, created_by TEXT, bid_request_id TEXT REFERENCES bid_requests(id));
CREATE TABLE company_documents (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  title TEXT NOT NULL,
  doc_type TEXT NOT NULL DEFAULT 'other',
  r2_key TEXT NOT NULL,
  filename TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  effective_date TEXT,
  expires_at TEXT,
  notes TEXT,
  uploaded_by TEXT,
  drive_mirrored_at TEXT
);
CREATE TABLE drive_mirror_folders (
  path_key TEXT PRIMARY KEY,
  drive_folder_id TEXT NOT NULL
);
CREATE TABLE job_files (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  title TEXT NOT NULL,
  doc_type TEXT NOT NULL DEFAULT 'other',
  r2_key TEXT NOT NULL,
  filename TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  notes TEXT,
  uploaded_by TEXT
, drive_mirrored_at TEXT, source TEXT NOT NULL DEFAULT 'dashboard', jobber_attachment_id TEXT);
CREATE TABLE system_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  value_type TEXT NOT NULL CHECK(value_type IN ('string','number','boolean','json')),
  category TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_by TEXT
);
CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  user_email TEXT NOT NULL,
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  details TEXT,
  ip_address TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE dead_letter_queue (
  id TEXT PRIMARY KEY,
  operation TEXT NOT NULL,
  payload TEXT,
  error_message TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0,
  max_retries INTEGER NOT NULL DEFAULT 3,
  status TEXT NOT NULL CHECK(status IN ('pending','retrying','resolved','dismissed')),
  next_retry_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  resolved_at TEXT
);
CREATE TABLE properties (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id),
  address TEXT NOT NULL,
  city TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'Arkansas',
  zip TEXT NOT NULL,
  property_type TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE communications (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id),
  job_id TEXT REFERENCES jobs(id),
  channel TEXT NOT NULL CHECK(channel IN ('phone_call','text_sms','email','portal_message','in_person','other')),
  direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')),
  summary TEXT NOT NULL,
  body TEXT,
  duration_seconds INTEGER,
  call_recording_url TEXT,
  sent_via TEXT,
  high_level_message_id TEXT,
  attachments TEXT,
  logged_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, twilio_sid TEXT);
CREATE TABLE estimate_line_items (
  id TEXT PRIMARY KEY,
  estimate_id TEXT NOT NULL REFERENCES estimates(id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  product_service TEXT NOT NULL,
  description TEXT NOT NULL,
  quantity REAL NOT NULL DEFAULT 1,
  unit TEXT,
  unit_price REAL NOT NULL,
  total REAL,
  includes_note TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, completion_status TEXT DEFAULT 'not_started', completed_date TEXT, blocked_by_line_item_id TEXT REFERENCES estimate_line_items(id));
CREATE TABLE estimate_sub_items (
  id TEXT PRIMARY KEY,
  parent_line_item_id TEXT NOT NULL REFERENCES estimate_line_items(id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL,
  vendor TEXT,
  quantity REAL,
  unit TEXT,
  unit_cost REAL NOT NULL,
  total_cost REAL,
  material_id TEXT REFERENCES vendor_materials(id),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, sub_id TEXT REFERENCES subcontractors(id));
CREATE TABLE payment_schedules (
  id TEXT PRIMARY KEY,
  estimate_id TEXT NOT NULL REFERENCES estimates(id) ON DELETE CASCADE,
  sort_order INTEGER NOT NULL,
  description TEXT NOT NULL,
  percentage REAL,
  fixed_amount REAL,
  amount REAL,
  is_deposit INTEGER DEFAULT 0,
  trigger TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE estimate_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  job_type TEXT NOT NULL,
  description TEXT,
  default_billing_model TEXT,
  line_items TEXT NOT NULL,
  default_payment_schedule TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE saved_reviews (
  id TEXT PRIMARY KEY,
  reviewer_name TEXT NOT NULL,
  review_date TEXT,
  rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
  review_text TEXT NOT NULL,
  source TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  task_group TEXT NOT NULL,
  task_group_order INTEGER NOT NULL,
  title TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('pending','in_progress','complete','skipped')),
  assigned_to TEXT,
  scheduled_date TEXT,
  completed_date TEXT,
  completed_by TEXT,
  notes TEXT,
  sort_order INTEGER NOT NULL,
  is_punch_list INTEGER DEFAULT 0,
  photo_ids TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE daily_logs (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  log_date TEXT NOT NULL,
  weather TEXT,
  work_performed TEXT NOT NULL,
  issues TEXT,
  materials_used TEXT,
  crew_on_site TEXT,
  hours_worked REAL,
  photo_ids TEXT,
  entered_via TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by TEXT
);
CREATE TABLE change_orders (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  change_order_number INTEGER NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  amount REAL NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('draft','sent','approved','rejected')),
  requested_date TEXT NOT NULL DEFAULT (datetime('now')),
  approved_date TEXT,
  client_signature TEXT,
  triggered_by_note_id TEXT REFERENCES smart_notes(id),
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, applied_at TEXT, end_date_extension_days INTEGER DEFAULT 0, signed_name TEXT, signed_ip TEXT);
CREATE TABLE schedule_entries (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  scheduled_date TEXT NOT NULL,
  trade_or_work TEXT NOT NULL,
  sub_id TEXT REFERENCES subcontractors(id),
  start_time TEXT,
  end_time TEXT,
  notes TEXT,
  notification_sent INTEGER DEFAULT 0,
  status TEXT NOT NULL CHECK(status IN ('scheduled','in_progress','completed','cancelled','weather_delay')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, bid_request_id TEXT REFERENCES bid_requests(id));
CREATE TABLE permits (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  permit_type TEXT NOT NULL,
  permit_number TEXT,
  status TEXT NOT NULL CHECK(status IN ('applied','approved','inspection_scheduled','passed','failed','closed')),
  applied_date TEXT,
  approved_date TEXT,
  inspection_date TEXT,
  inspection_result TEXT,
  cost REAL,
  document_id TEXT REFERENCES documents(id),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE warranties (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  claim_date TEXT NOT NULL,
  description TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('reported','scheduled','resolved')),
  resolution TEXT,
  resolved_date TEXT,
  cost REAL,
  photo_ids TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, submitted_by TEXT NOT NULL DEFAULT 'owner'
  CHECK(submitted_by IN ('owner', 'client')), viewed_by_owner INTEGER NOT NULL DEFAULT 0);
CREATE TABLE time_entries (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  worker TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('general','pm_skilled')),
  clock_in TEXT NOT NULL,
  clock_out TEXT,
  hours REAL,
  hourly_rate REAL,
  labor_cost REAL,
  notes TEXT,
  entered_via TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE billing_cycles (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  cycle_number INTEGER NOT NULL,
  period_start TEXT NOT NULL,
  period_end TEXT NOT NULL,
  is_final_cycle INTEGER DEFAULT 0,
  status TEXT NOT NULL CHECK(status IN ('planning','active','reconciling','closed')),
  projected_materials REAL DEFAULT 0,
  projected_labor REAL DEFAULT 0,
  projected_subs REAL DEFAULT 0,
  projected_subtotal REAL,
  pm_fee_rate REAL NOT NULL DEFAULT 0.10,
  contractor_fee_rate REAL NOT NULL DEFAULT 0.20,
  projected_pm_fee REAL,
  projected_contractor_fee REAL,
  projected_total REAL,
  actual_materials REAL DEFAULT 0,
  actual_labor REAL DEFAULT 0,
  actual_subs REAL DEFAULT 0,
  actual_subtotal REAL,
  actual_pm_fee REAL,
  actual_contractor_fee REAL,
  actual_total REAL,
  delta REAL,
  credit_from_prior REAL DEFAULT 0,
  credit_to_next REAL DEFAULT 0,
  invoice_id TEXT REFERENCES invoices(id),
  reconciliation_invoice_id TEXT REFERENCES invoices(id),
  reconciliation_date TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, scope_allocations TEXT);
CREATE TABLE mileage (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  trip_purpose TEXT NOT NULL,
  start_location TEXT,
  end_location TEXT,
  distance_miles REAL NOT NULL,
  trip_date TEXT NOT NULL,
  irs_rate REAL,
  deduction_amount REAL,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE lien_waivers (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES jobs(id),
  sub_id TEXT NOT NULL REFERENCES subcontractors(id),
  waiver_type TEXT NOT NULL CHECK(waiver_type IN ('conditional','unconditional','partial','final')),
  payment_amount REAL NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('requested','received','filed')),
  requested_date TEXT NOT NULL DEFAULT (datetime('now')),
  received_date TEXT,
  document_id TEXT REFERENCES documents(id),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE vendor_materials (
  id TEXT PRIMARY KEY,
  vendor_name TEXT NOT NULL,
  material_name TEXT NOT NULL,
  category TEXT NOT NULL,
  unit TEXT NOT NULL,
  last_price REAL NOT NULL,
  last_purchased_date TEXT,
  average_price REAL,
  price_history TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE receipt_photos (
  id TEXT PRIMARY KEY,
  photo_id TEXT NOT NULL UNIQUE REFERENCES photos(id) ON DELETE CASCADE,
  ai_vendor TEXT,
  ai_amount REAL,
  ai_date TEXT,
  ai_category TEXT,
  ai_confidence REAL,
  expense_id TEXT REFERENCES expenses(id),
  processing_status TEXT NOT NULL CHECK(processing_status IN ('pending','processed','confirmed','failed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, extracted_items TEXT, match_results TEXT);
CREATE TABLE smart_notes (
  id TEXT PRIMARY KEY,
  job_id TEXT REFERENCES jobs(id),
  raw_content TEXT NOT NULL,
  ai_summary TEXT,
  ai_category TEXT,
  ai_extracted_tasks TEXT,
  ai_extracted_expense TEXT,
  ai_extracted_change_order TEXT,
  is_processed INTEGER DEFAULT 0,
  processing_status TEXT,
  entered_via TEXT NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE document_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  template_type TEXT NOT NULL,
  content TEXT NOT NULL,
  merge_fields TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  version INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, previous_version_id TEXT);
CREATE TABLE notification_templates (
  id TEXT PRIMARY KEY,
  trigger_event TEXT NOT NULL,
  name TEXT NOT NULL,
  recipient_type TEXT NOT NULL CHECK(recipient_type IN ('client','subcontractor','internal','owner')),
  channel TEXT NOT NULL CHECK(channel IN ('sms','email','push','in_app')),
  subject TEXT,
  body_template TEXT NOT NULL,
  merge_fields TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  delay_minutes INTEGER DEFAULT 0,
  send_time TEXT,
  phase TEXT,
  sort_order INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE social_posts (
  id TEXT PRIMARY KEY,
  post_type TEXT NOT NULL CHECK(post_type IN ('job_completion','seasonal_tips','tips_tricks','promotion','review_highlight','manual')),
  status TEXT NOT NULL CHECK(status IN ('draft','pending_approval','approved','scheduled','published','rejected','failed')),
  caption TEXT NOT NULL,
  hashtags TEXT,
  platform TEXT NOT NULL CHECK(platform IN ('both','facebook_only','instagram_only')),
  scheduled_date TEXT,
  published_date TEXT,
  job_id TEXT REFERENCES jobs(id),
  photo_ids TEXT,
  ai_generated_image_url TEXT,
  facebook_post_id TEXT,
  instagram_post_id TEXT,
  facebook_url TEXT,
  instagram_url TEXT,
  engagement_data TEXT,
  rejection_reason TEXT,
  generated_by TEXT NOT NULL,
  approved_by TEXT,
  approved_date TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, image_variation_index INTEGER NOT NULL DEFAULT 0);
CREATE TABLE content_schedules (
  id TEXT PRIMARY KEY,
  month INTEGER NOT NULL,
  year INTEGER NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('draft','active','completed')),
  generated_date TEXT NOT NULL DEFAULT (datetime('now')),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE billing_schedule (
  id            TEXT PRIMARY KEY,
  job_id        TEXT NOT NULL REFERENCES jobs(id),
  billing_model TEXT NOT NULL,
  sequence      INTEGER NOT NULL,                 -- display / draw order
  label         TEXT NOT NULL,                    -- e.g. "Draw 1 — Materials Deposit"
  trigger_type  TEXT NOT NULL,                    -- milestone | trade_completion | cost_plus_cycle
  trigger_ref   TEXT,                             -- milestone #, task_group name, or cycle marker
  percentage    REAL,                             -- fixed_price draws (nullable)
  amount        REAL,                             -- scaffolded dollar amount (nullable)
  period_start  TEXT,                             -- cost_plus cycle window start (nullable)
  period_end    TEXT,                             -- cost_plus cycle window end (nullable)
  status        TEXT NOT NULL DEFAULT 'draft',    -- draft until Sprint 9 invoices it
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE device_tokens (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id),
  platform      TEXT NOT NULL CHECK (platform IN ('ios','android','web')),
  token         TEXT NOT NULL,
  is_active     INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  last_seen_at  TEXT
);
CREATE TABLE warranty_calls (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open', 'scheduled', 'completed', 'cancelled')),
  assigned_to TEXT REFERENCES users(id),
  assigned_sub_id TEXT REFERENCES subcontractors(id),
  scheduled_date TEXT,
  scheduled_end TEXT,
  completed_date TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE google_calendar_events (
  id TEXT PRIMARY KEY,
  calendar_id TEXT NOT NULL,
  title TEXT NOT NULL,
  start_time TEXT NOT NULL,
  end_time TEXT NOT NULL,
  meet_link TEXT,
  description TEXT,
  event_type TEXT DEFAULT 'meeting',
  synced_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE job_documents (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), template_type TEXT NOT NULL, filename TEXT NOT NULL, r2_key TEXT NOT NULL, generated_at TEXT NOT NULL DEFAULT (datetime('now')), generated_by TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), review_status TEXT NOT NULL DEFAULT 'manual', auto_generated INTEGER NOT NULL DEFAULT 0, trigger_event TEXT, related_record_id TEXT, reviewed_at TEXT, reviewed_by TEXT, signature_status TEXT NOT NULL DEFAULT 'none', boldsign_document_id TEXT, signature_sent_at TEXT, signature_completed_at TEXT, signed_r2_key TEXT, signer_email TEXT, signer_name TEXT);
CREATE TABLE signature_events (
  id TEXT PRIMARY KEY,
  job_document_id TEXT NOT NULL REFERENCES job_documents(id),
  boldsign_document_id TEXT,
  event_type TEXT NOT NULL,
  raw_payload TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE payers (
  id TEXT PRIMARY KEY,
  company_name TEXT,
  contact_name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  billing_address TEXT,
  billing_city TEXT,
  billing_state TEXT,
  billing_zip TEXT,
  stripe_customer_id TEXT,
  stripe_payment_method_id TEXT,
  card_brand TEXT,
  card_last4 TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by TEXT
);
CREATE TABLE line_item_catalog (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  unit TEXT,
  unit_price REAL NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE client_lien_waivers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  waiver_type TEXT NOT NULL DEFAULT 'conditional'
    CHECK(waiver_type IN ('conditional', 'final')),
  payment_amount REAL NOT NULL,
  invoice_id TEXT REFERENCES invoices(id),
  boldsign_document_id TEXT,
  boldsign_template_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK(status IN ('pending','sent','signed','declined','failed')),
  sent_at TEXT,
  signed_at TEXT,
  r2_key TEXT,
  document_id TEXT REFERENCES documents(id),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, error_message TEXT);
CREATE TABLE punch_lists (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'open'
    CHECK(status IN ('open','sent','closed')),
  scheduled_date TEXT,
  sent_at TEXT,
  closed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, name TEXT NOT NULL DEFAULT 'Punch List');
CREATE TABLE punch_list_items (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  punch_list_id TEXT NOT NULL REFERENCES punch_lists(id) ON DELETE CASCADE,
  job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  description TEXT NOT NULL,
  sub_id TEXT REFERENCES subcontractors(id),
  photo_ids TEXT,
  status TEXT NOT NULL DEFAULT 'open'
    CHECK(status IN ('open','done')),
  scheduled_date TEXT,
  completed_at TEXT,
  completed_note TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE punch_list_sub_tokens (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  punch_list_id TEXT NOT NULL REFERENCES punch_lists(id) ON DELETE CASCADE,
  sub_id TEXT NOT NULL REFERENCES subcontractors(id),
  token TEXT NOT NULL UNIQUE,
  notified_at TEXT,
  reminder_sent_at TEXT,
  followup_sent_at TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE sub_access_tokens (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  sub_id     TEXT NOT NULL UNIQUE REFERENCES subcontractors(id),
  token      TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_viewed_at TEXT
);
CREATE TABLE client_contacts (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  label TEXT NOT NULL,
  contact_type TEXT NOT NULL CHECK(contact_type IN ('phone', 'email')),
  value TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE tag_definitions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  tag_text TEXT NOT NULL UNIQUE,
  archived INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE client_tags (
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  tag_definition_id TEXT NOT NULL REFERENCES tag_definitions(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (client_id, tag_definition_id)
);
CREATE TABLE referral_sources (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  label TEXT NOT NULL UNIQUE,
  archived INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE google_reviews (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  google_review_id TEXT UNIQUE,
  reviewer_name TEXT NOT NULL,
  reviewer_photo_url TEXT,
  star_rating INTEGER NOT NULL CHECK(star_rating BETWEEN 1 AND 5),
  comment_text TEXT,
  review_created_at TEXT NOT NULL,
  review_updated_at TEXT,
  reply_text TEXT,
  reply_sent_at TEXT,
  reply_source TEXT CHECK(reply_source IN ('cms', 'external')),
  matched_client_id TEXT REFERENCES clients(id),
  match_confidence TEXT CHECK(match_confidence IN ('confirmed', 'suggested')),
  entry_source TEXT NOT NULL DEFAULT 'manual' CHECK(entry_source IN ('manual', 'sync')),
  synced_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE expense_line_items (
  id                          TEXT    PRIMARY KEY,
  receipt_photo_id            TEXT    NOT NULL,
  description                 TEXT    NOT NULL,
  quantity                    REAL,
  unit                        TEXT,
  unit_price                  REAL,
  amount                      REAL    NOT NULL,
  -- Match A: estimate_sub_items (for bid-accuracy variance report)
  matched_estimate_sub_item_id TEXT,
  -- Match B: vendor_materials (for pricing catalog updates)
  matched_vendor_material_id  TEXT,
  match_confidence            REAL,
  -- Set when user confirms → links to the expenses row created from this line
  expense_id                  TEXT,
  created_at                  TEXT    NOT NULL DEFAULT (datetime('now'))
, ai_suggested_sub_item_id TEXT);
CREATE TABLE bid_requests (
  id                    TEXT PRIMARY KEY,
  estimate_id           TEXT REFERENCES estimates(id),
  job_id                TEXT REFERENCES jobs(id),
  estimate_sub_item_id  TEXT REFERENCES estimate_sub_items(id),
  title                 TEXT NOT NULL,
  scope_description     TEXT NOT NULL,
  quantities_notes      TEXT,
  needed_by_date        TEXT,
  status                TEXT NOT NULL DEFAULT 'open'
                          CHECK(status IN ('open','awarded','cancelled')),
  bid_mode              TEXT NOT NULL DEFAULT 'sealed'
                          CHECK(bid_mode IN ('sealed','open')),
  notify_losers         INTEGER NOT NULL DEFAULT 1,
  awarded_sub_id        TEXT REFERENCES subcontractors(id),
  awarded_bid_id        TEXT,
  created_at            TEXT NOT NULL DEFAULT (datetime('now'))
, estimate_line_item_id TEXT REFERENCES estimate_line_items(id));
CREATE TABLE bid_request_recipients (
  id              TEXT PRIMARY KEY,
  bid_request_id  TEXT NOT NULL REFERENCES bid_requests(id),
  sub_id          TEXT NOT NULL REFERENCES subcontractors(id),
  portal_token    TEXT NOT NULL UNIQUE,
  sent_at         TEXT,
  viewed_at       TEXT,
  created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE bid_submissions (
  id               TEXT PRIMARY KEY,
  bid_request_id   TEXT NOT NULL REFERENCES bid_requests(id),
  sub_id           TEXT NOT NULL REFERENCES subcontractors(id),
  price            REAL NOT NULL,
  notes            TEXT,
  attachment_photo_id TEXT REFERENCES photos(id),
  status           TEXT NOT NULL DEFAULT 'submitted'
                     CHECK(status IN ('submitted','won','lost')),
  submitted_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE selections (
  id                      TEXT PRIMARY KEY,
  estimate_id             TEXT REFERENCES estimates(id),
  job_id                  TEXT REFERENCES jobs(id),
  estimate_sub_item_id    TEXT REFERENCES estimate_sub_items(id),
  title                   TEXT NOT NULL,
  category                TEXT,
  location                TEXT,
  allowance_amount        REAL NOT NULL,
  is_shared_allowance     INTEGER NOT NULL DEFAULT 0,
  shared_allowance_group_id TEXT,
  required                INTEGER NOT NULL DEFAULT 1,
  deadline_date           TEXT,
  public_instructions     TEXT,
  internal_notes          TEXT,
  status                  TEXT NOT NULL DEFAULT 'pending'
                            CHECK(status IN ('pending','sent','approved')),
  created_at              TEXT NOT NULL DEFAULT (datetime('now'))
, chosen_choice_id TEXT REFERENCES selection_choices(id));
CREATE TABLE selection_choices (
  id                          TEXT PRIMARY KEY,
  selection_id                TEXT NOT NULL REFERENCES selections(id),
  title                       TEXT NOT NULL,
  description                 TEXT,
  price                       REAL NOT NULL,
  photo_ids                   TEXT,
  vendor_name                 TEXT,
  is_client_added             INTEGER NOT NULL DEFAULT 0,
  approved                    INTEGER NOT NULL DEFAULT 0,
  approved_at                 TEXT,
  client_signature_document_id TEXT REFERENCES documents(id),
  created_at                  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE subcontractor_packet_documents (
  id              TEXT PRIMARY KEY,
  packet_id       TEXT NOT NULL REFERENCES subcontractor_packets(id),
  document_type   TEXT NOT NULL CHECK(document_type IN ('w9','coi_general_liability','coi_workers_comp','license')),
  document_id     TEXT REFERENCES documents(id),
  expiration_date TEXT,
  uploaded_at     TEXT NOT NULL DEFAULT (datetime('now'))
, captured_tax_id TEXT, captured_license_number TEXT);
CREATE TABLE IF NOT EXISTS "subcontractor_packets" (
  id                            TEXT PRIMARY KEY,
  sub_id                        TEXT NOT NULL REFERENCES subcontractors(id),
  portal_token                  TEXT NOT NULL UNIQUE,
  status                        TEXT NOT NULL DEFAULT 'sent'
                                  CHECK(status IN ('sent','in_progress','submitted','approved','awaiting_signature','signed')),
  workers_comp_exempt           INTEGER NOT NULL DEFAULT 0,
  workers_comp_exemption_reason TEXT,
  sent_at                       TEXT NOT NULL DEFAULT (datetime('now')),
  submitted_at                  TEXT,
  approved_at                   TEXT,
  signed_at                     TEXT,
  agreement_document_id         TEXT REFERENCES documents(id),
  created_at                    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "documents" (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  file_type TEXT NOT NULL,
  file_size INTEGER,
  r2_key TEXT NOT NULL,
  r2_url TEXT NOT NULL,
  google_drive_id TEXT,
  google_drive_url TEXT,
  mirror_status TEXT,
  mirror_date TEXT,
  context_type TEXT NOT NULL CHECK(context_type IN (
    'job',
    'client',
    'estimate',
    'company',
    'template',
    'selection',
    'subcontractor_packet',
    'subcontractor_agreement'
  )),
  job_id TEXT REFERENCES jobs(id),
  client_id TEXT REFERENCES clients(id),
  estimate_id TEXT REFERENCES estimates(id),
  document_category TEXT NOT NULL,
  is_signed INTEGER DEFAULT 0,
  signed_date TEXT,
  signature_data TEXT,
  share_token TEXT UNIQUE,
  share_expiration TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  uploaded_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE punch_list_name_presets (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  name TEXT NOT NULL UNIQUE,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "integration_connections" (
  id TEXT PRIMARY KEY,
  service TEXT NOT NULL CHECK(service IN (
    'stripe','quickbooks','twilio','high_level','google_drive',
    'facebook','instagram','replicate','google_calendar',
    'google_business_profile'
  )),
  status TEXT NOT NULL CHECK(status IN ('connected','disconnected','error','pending')),
  access_token TEXT,
  refresh_token TEXT,
  token_expiry TEXT,
  account_id TEXT,
  configuration TEXT,
  last_sync TEXT,
  last_error TEXT,
  connected_at TEXT,
  connected_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE vendor_subscriptions (
  id TEXT PRIMARY KEY,
  service_name TEXT NOT NULL,
  category TEXT NOT NULL CHECK(category IN (
    'infrastructure', 'communications', 'documents', 'payments',
    'accounting', 'ai_cloud', 'marketing_crm', 'development'
  )),
  cost_amount REAL,
  cost_period TEXT CHECK(
    cost_period IS NULL OR cost_period IN ('monthly', 'annual', 'usage_based', 'one_time')
  ),
  currency TEXT NOT NULL DEFAULT 'USD',
  renewal_date TEXT,
  auto_renews INTEGER NOT NULL DEFAULT 1,
  account_email TEXT,
  account_id TEXT,
  contact_name TEXT,
  contact_email TEXT,
  contact_phone TEXT,
  support_notes TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "estimate_requests" (
  id TEXT PRIMARY KEY,
  request_number INTEGER NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK(status IN (
    'new_request','appointment_set','visit_done','building','sent','follow_up','won','lost'
  )),
  client_id TEXT,
  property_address TEXT NOT NULL,
  property_city TEXT NOT NULL,
  property_state TEXT NOT NULL DEFAULT 'Arkansas',
  property_zip TEXT NOT NULL,
  job_type TEXT NOT NULL,
  lead_source TEXT NOT NULL,
  lead_source_detail TEXT,
  high_level_opportunity_id TEXT,
  appointment_date TEXT,
  appointment_completed INTEGER DEFAULT 0,
  visit_notes TEXT,
  visit_photo_ids TEXT,
  estimate_id TEXT,
  sent_date TEXT,
  follow_up_count INTEGER DEFAULT 0,
  last_follow_up_date TEXT,
  lost_reason TEXT,
  lost_notes TEXT,
  converted_job_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by TEXT,
  appointment_time TEXT,
  lat REAL,
  lon REAL,
  last_sms_at TEXT,
  last_sms_preview TEXT,
  source TEXT DEFAULT 'manual'
    CHECK(source IN ('manual', 'inbound_sms', 'high_level', 'website_form', 'thumbtack')),
  follow_up_sequence_active INTEGER DEFAULT 0,
  follow_up_completed_at TEXT,
  proposal_review_date TEXT,
  lead_outreach_sequence_active INTEGER DEFAULT 0,
  lead_outreach_count INTEGER DEFAULT 0,
  last_outreach_date TEXT,
  lead_outreach_completed_at TEXT,
  scope_draft TEXT,
  sketches TEXT,
  property_id TEXT,
  thumbtack_negotiation_id TEXT UNIQUE,
  thumbtack_raw_payload TEXT,
  contact_name TEXT,
  contact_phone TEXT,
  contact_email TEXT
, job_type_detail TEXT);
CREATE TABLE pending_quote_imports (
  id TEXT PRIMARY KEY,
  source TEXT NOT NULL DEFAULT 'email',
  from_address TEXT,
  subject TEXT,
  received_at TEXT NOT NULL,
  raw_text TEXT,
  extraction_json TEXT,
  extraction_error TEXT,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'assigned', 'discarded')),
  assigned_estimate_id TEXT,
  assigned_line_item_id TEXT,
  created_estimate_sub_item_ids TEXT,
  resolved_at TEXT,
  resolved_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, attachments TEXT);
CREATE TABLE IF NOT EXISTS "notification_logs" (
  id TEXT PRIMARY KEY,
  template_id TEXT NOT NULL REFERENCES notification_templates(id),
  trigger_event TEXT NOT NULL,
  recipient_type TEXT NOT NULL,
  recipient_name TEXT NOT NULL,
  recipient_contact TEXT NOT NULL,
  channel TEXT NOT NULL,
  subject TEXT,
  body TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('queued','sending','sent','delivered','failed','bounced')),
  error_message TEXT,
  job_id TEXT REFERENCES jobs(id),
  client_id TEXT REFERENCES clients(id),
  estimate_request_id TEXT REFERENCES estimate_requests(id),
  communication_id TEXT REFERENCES communications(id),
  sent_at TEXT,
  delivered_at TEXT,
  external_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  scheduled_for TEXT,
  retry_count INTEGER NOT NULL DEFAULT 0,
  next_retry_at TEXT,
  recipient_user_id TEXT,
  is_read INTEGER NOT NULL DEFAULT 0,
  read_at TEXT,
  link_path TEXT,
  dedupe_key TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_jobs_created_at ON jobs(created_at);
CREATE INDEX idx_jobs_completed_at ON jobs(completed_at);
CREATE INDEX idx_jobs_status ON jobs(status);
CREATE INDEX idx_quotes_transitioned_at ON quotes(transitioned_at);
CREATE INDEX idx_payments_collected_at ON payments(collected_at);
CREATE INDEX idx_files_job ON files(job_id, category);
CREATE INDEX idx_files_lead ON files(lead_id);
CREATE INDEX idx_files_taken ON files(taken_at);
CREATE INDEX idx_files_social ON files(category) WHERE category = 'social_ready';
CREATE INDEX idx_sync_log_started ON sync_log(started_at);
CREATE INDEX idx_audit_user_time ON audit_log(user_id, occurred_at);
CREATE INDEX idx_audit_entity ON audit_log(entity_type, entity_id);
CREATE INDEX idx_quotes_client_id ON quotes(client_id);
CREATE INDEX idx_notes_created ON notes(created_at DESC);
CREATE INDEX idx_notes_status ON notes(status);
CREATE INDEX idx_notes_category ON notes(category);
CREATE INDEX idx_subs_company ON subcontractors(company COLLATE NOCASE);
CREATE INDEX idx_subs_trade ON subcontractors(trade);
CREATE INDEX idx_subs_status ON subcontractors(active_status);
CREATE UNIQUE INDEX idx_dlq_unique_open
  ON sync_dead_letters(job_name, entity_type, entity_id)
  WHERE resolved_at IS NULL;
CREATE INDEX idx_dlq_unresolved
  ON sync_dead_letters(resolved_at, last_seen_at);
CREATE INDEX idx_photos_job ON photos(job_id, taken_at DESC);
CREATE INDEX idx_photos_category ON photos(category);
CREATE INDEX idx_photos_created ON photos(created_at DESC);
CREATE INDEX idx_notes_job ON notes(job_id);
CREATE INDEX idx_expenses_pending_pushback
  ON expenses(entered_via, pushed_to_jobber_at);
CREATE INDEX idx_photos_drive_mirrored ON photos(drive_mirrored_at);
CREATE INDEX idx_expenses_drive_mirrored ON expenses(drive_mirrored_at);
CREATE INDEX idx_company_docs_type ON company_documents(doc_type, created_at DESC);
CREATE INDEX idx_company_docs_created ON company_documents(created_at DESC);
CREATE INDEX idx_job_files_job_type ON job_files(job_id, doc_type, created_at DESC);
CREATE INDEX idx_job_files_created ON job_files(created_at DESC);
CREATE INDEX idx_job_files_drive_mirrored ON job_files(drive_mirrored_at);
CREATE UNIQUE INDEX idx_job_files_jobber_attachment_id
  ON job_files(jobber_attachment_id) WHERE jobber_attachment_id IS NOT NULL;
CREATE INDEX idx_jobs_client_id ON jobs(client_id);
CREATE INDEX idx_jobs_job_type ON jobs(job_type);
CREATE INDEX idx_jobs_start_date ON jobs(start_date);
CREATE INDEX idx_tasks_job_id ON tasks(job_id);
CREATE INDEX idx_tasks_status ON tasks(status);
CREATE INDEX idx_tasks_scheduled_date ON tasks(scheduled_date);
CREATE INDEX idx_estimates_request_id ON estimates(request_id);
CREATE INDEX idx_estimates_status ON estimates(status);
CREATE INDEX idx_estimate_line_items_estimate_id ON estimate_line_items(estimate_id);
CREATE INDEX idx_estimate_sub_items_parent_id ON estimate_sub_items(parent_line_item_id);
CREATE INDEX idx_invoices_job_id ON invoices(job_id);
CREATE INDEX idx_invoices_status ON invoices(status);
CREATE INDEX idx_invoices_due_date ON invoices(due_date);
CREATE INDEX idx_payments_invoice_id ON payments(invoice_id);
CREATE INDEX idx_payments_job_id ON payments(job_id);
CREATE INDEX idx_expenses_job_id ON expenses(job_id);
CREATE INDEX idx_expenses_incurred_date ON expenses(incurred_date);
CREATE INDEX idx_time_entries_job_id ON time_entries(job_id);
CREATE INDEX idx_billing_cycles_job_id ON billing_cycles(job_id);
CREATE INDEX idx_photos_job_id ON photos(job_id);
CREATE INDEX idx_photos_photo_type ON photos(photo_type);
CREATE INDEX idx_photos_taken_at ON photos(taken_at);
CREATE INDEX idx_photos_is_social_ready ON photos(is_social_ready) WHERE is_social_ready = 1;
CREATE INDEX idx_clients_email ON clients(email);
CREATE INDEX idx_clients_phone ON clients(phone);
CREATE INDEX idx_clients_high_level_contact_id ON clients(high_level_contact_id);
CREATE INDEX idx_communications_client_id ON communications(client_id);
CREATE INDEX idx_communications_job_id ON communications(job_id);
CREATE INDEX idx_communications_created_at ON communications(created_at);
CREATE INDEX idx_social_posts_status ON social_posts(status);
CREATE INDEX idx_social_posts_scheduled_date ON social_posts(scheduled_date);
CREATE INDEX idx_schedule_entries_job_id ON schedule_entries(job_id);
CREATE INDEX idx_schedule_entries_scheduled_date ON schedule_entries(scheduled_date);
CREATE INDEX idx_schedule_entries_sub_id ON schedule_entries(sub_id);
CREATE INDEX idx_audit_logs_entity_type ON audit_logs(entity_type);
CREATE INDEX idx_audit_logs_entity_id ON audit_logs(entity_id);
CREATE INDEX idx_audit_logs_created_at ON audit_logs(created_at);
CREATE INDEX idx_smart_notes_job_id ON smart_notes(job_id);
CREATE INDEX idx_dlq_status ON dead_letter_queue(status);
CREATE INDEX idx_change_orders_job_id ON change_orders(job_id);
CREATE INDEX idx_permits_job_id ON permits(job_id);
CREATE INDEX idx_warranties_job_id ON warranties(job_id);
CREATE INDEX idx_daily_logs_job_id ON daily_logs(job_id);
CREATE INDEX idx_daily_logs_log_date ON daily_logs(log_date);
